import * as T from './vendor/three.module.js';
import {createProduct} from './product-models.js';
import {PRODUCTS} from './product-catalog.js';
export const DISPLAYS=[{id:'endcap',x:-5,z:5.5,ids:['chips','candyRoll','granola','batteries','tissues','bulb','water','glassSoda']},{id:'spinner',x:3,z:-1.8,ids:['candyRoll','chocolate','granola','batteries','bulb','tissues','juicePouch','water','lemonTea','glassSoda','peanuts','crackers']},{id:'spinner-news',x:-.6,z:-1.8,ids:['candyRoll','chocolate','granola','peanuts','crackers','shortbread','batteries','bulb','tissues','juicePouch','lemonTea','glassSoda']},{id:'spinner-travel',x:7.8,z:-2.4,ids:['water','sportsDrink','thermos','juicePouch','glassSoda','lemonTea','granola','chocolate','candyRoll','batteries','tissues','bulb']}];
DISPLAYS.push({id:'wire-snacks',kind:'wire',x:8.2,z:6.8,ids:['chips','pretzels','popcorn','granola','peanuts','shortbread']},{id:'wire-bakery',kind:'wire',x:-8.1,z:7.45,ids:['bread','donuts','candyRoll','chocolate','crackers','cookieTin']});
export const isSpinner=id=>id?.startsWith('spinner');
export const spinnerStep=(s,id)=>id==='spinner'?(s.spinnerStep||0):(s.spinnerSteps?.[id]||0);
export const spinnerBusy=(s,id)=>id==='spinner'?(s.spinnerBusy||0):(s.spinnerBusies?.[id]||0);
export function displaySlots(id,s={}){const slots=[];for(const d of DISPLAYS){d.ids.forEach((sku,i)=>{if(sku!==id)return;const angle=isSpinner(d.id)?(Math.floor(i/3)+spinnerStep(s,d.id))*Math.PI/2:Math.PI/2;const lateral=isSpinner(d.id)?(i%3-1)*.20:(i-(d.ids.length-1)/2)*(d.kind==='wire'?.19:.21);const radius=isSpinner(d.id)?.40:d.kind==='wire'?.32:.49;const x=d.x-Math.sin(angle)*radius+Math.cos(angle)*lateral,z=d.z-Math.cos(angle)*radius-Math.sin(angle)*lateral;slots.push({id,fixture:d.id,key:'display:'+d.id+':'+i,y:1.3175+PRODUCTS[id].h/2,x,z,yaw:angle,depth:0});});}return slots;}
export function installDisplays(w){const a=w.a,metal=a.get('metal'),dark=a.plain(0x40483d),wood=a.get('wood');w.displayProducts=[];w.spinners={};for(const d of DISPLAYS){const g=new T.Group();g.position.set(d.x,0,d.z);w.scene.add(g);g.name='display-'+d.id;const spinner=isSpinner(d.id);if(spinner){w.spinners[d.id]=g;if(d.id==='spinner')w.spinner=g;w.box(0,.12,0,1.25,.15,1.25,dark,false,g);w.box(0,1,0,.06,1.8,.06,metal,false,g);for(const y of[.28,.79,1.29]){w.box(0,y,0,.95,.05,.95,metal,false,g);for(const side of[-1,1]){w.box(side*.49,y+.025,0,.025,.055,1,metal,false,g);w.box(0,y+.025,side*.49,1,.055,.025,metal,false,g);}}w.box(0,1.87,0,1.05,.22,1.05,dark,false,g);for(let side=0;side<4;side++){const label=new T.Mesh(new T.PlaneGeometry(.92,.16),new T.MeshBasicMaterial({map:a.sign(d.id==='spinner-travel'?'TRAVEL ESSENTIALS':d.id==='spinner-news'?'SNACKS TO GO':'QUICK PICK',{bg:'#424b3f',fg:'#ded0a6',aspect:6,size:128}),toneMapped:false}));label.position.set(Math.sin(side*Math.PI/2)*.533,1.87,Math.cos(side*Math.PI/2)*.533);label.rotation.y=side*Math.PI/2;label.userData.target={id:'spinner',key:d.id};g.add(label);}w.solids.push({x:d.x,z:d.z,w:1.3,d:1.3});g.traverse(o=>{if(o.isMesh)o.userData.target={id:'spinner',key:d.id};});w.target('spinner',d.id,d.x,1.4,d.z,'旋转小货架');}else if(d.kind==='wire'){const wire=a.plain(0x70796b);w.box(0,.13,0,.78,.12,1.36,dark,false,g);for(const x of[-.36,.36])for(const z of[-.63,.63])w.box(x,.90,z,.035,1.55,.035,metal,false,g);for(const y of[.28,.79,1.29]){w.box(0,y,0,.72,.035,1.30,wood,false,g);for(const z of[-.64,.64])w.box(0,y+.13,z,.74,.025,.025,wire,false,g);for(let z=-.59;z<.64;z+=.15)w.box(-.37,y+.07,z,.022,.16,.022,wire,false,g);}w.solids.push({x:d.x,z:d.z,w:.82,d:1.4,fixture:d.id});}else{for(const z of[-.95,.95])for(const x of[-.5,.5])w.box(x,1,z,.05,2,.06,metal,false,g);for(const y of[.28,.79,1.29])w.box(0,y,0,1.05,.05,1.95,wood,false,g);w.box(.35,1,0,.06,2,1.95,dark,false,g);w.solids.push({x:d.x,z:d.z,w:1.1,d:2});}
 for(let row=0;row<3;row++)d.ids.forEach((id,i)=>{const slot=displaySlots(id).find(s=>s.fixture===d.id),m=createProduct(a,id);m.position.set(slot.x-d.x,[.3075,.8175,1.3175][row]+PRODUCTS[id].h/2,slot.z-d.z);m.rotation.y=slot.yaw;g.add(m);if(spinner)m.traverse(o=>{if(o.isMesh)o.userData.target={id:'spinner',key:d.id};});w.displayProducts.push({m,key:slot.key,row});});}}
export function updateDisplays(w,s,dt){for(const[id,g]of Object.entries(w.spinners||{})){const target=spinnerStep(s,id)*Math.PI/2;g.rotation.y=spinnerBusy(s,id)?T.MathUtils.damp(g.rotation.y,target,10,dt||.016):target;}const removed=new Set(s.removedShelfSlots||[]);for(const a of s.actors||[])if(a.shoppingPose&&a.browseTime/(a.shoppingDuration||6)>=.445&&a.shoppingTarget?.fixture)removed.add(a.shoppingTarget.key);for(const p of w.displayProducts||[]){const visible=p.row!==2||!removed.has(p.key);p.m.visible=visible;if(p.instance&&p.lastVisible!==visible){p.instance.setMatrixAt(p.instanceIndex,visible?p.baseMatrix:new T.Matrix4().makeScale(0,0,0));p.instance.instanceMatrix.needsUpdate=true;p.lastVisible=visible;}}}
// Repeated facings share one GPU submission per product and fixture. The top
// facing can still disappear independently when a customer picks it up.
export function batchDisplayProducts(w){const groups=new Map();for(const p of w.displayProducts){const m=p.m,key=m.parent.uuid+':'+m.userData.product;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(p);}for(const list of groups.values()){if(list.length<2)continue;const first=list[0].m,mesh=new T.InstancedMesh(first.geometry,first.material,list.length);mesh.castShadow=true;mesh.receiveShadow=true;mesh.userData={...first.userData,sensorOnly:true,decorative:true};first.parent.add(mesh);list.forEach((p,i)=>{p.m.updateMatrix();mesh.setMatrixAt(i,p.m.matrix);p.instance=mesh;p.instanceIndex=i;p.baseMatrix=p.m.matrix.clone();p.lastVisible=true;p.m.removeFromParent();});}}
